// 误以为拒绝已经记住；落盘成功时返回 nil，由调用方返回业务拒绝本身。
func (r *Registry) recordRevokeRejection(key, sig string, req RevokeAuthorizationRequest, bizErr error) error {
	r.state.Requests[key] = request{
